3	import com.example.starter.firmware.domain.ReceiptResult;
4	import com.example.starter.firmware.domain.RolloutTask;
5	import com.example.starter.firmware.domain.TaskStatus;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.jdbc.core.RowMapper;
8	import org.springframework.jdbc.support.GeneratedKeyHolder;
9	import org.springframework.jdbc.support.KeyHolder;
10	import org.springframework.stereotype.Repository;
11	
12	import java.sql.PreparedStatement;
13	import java.util.List;
14	import java.util.Optional;
15	
16	/**
17	 * 投放任务数据访问。同设备同发布单由唯一约束 uk_task_release_device 保证最多一条。
18	 */
19	@Repository
20	public class TaskRepository {
21	
22	    private static final RowMapper<RolloutTask> MAPPER = (rs, rowNum) -> {
23	        String firstResult = rs.getString("first_result");
24	        return new RolloutTask(rs.getLong("id"), rs.getLong("release_id"), rs.getString("device_id"),
25	                TaskStatus.valueOf(rs.getString("status")),
26	                firstResult == null ? null : ReceiptResult.valueOf(firstResult));
27	    };
28	
29	    private static final String COLUMNS = "id, release_id, device_id, status, first_result";
30	
31	    private final JdbcTemplate jdbc;
32	
33	    public TaskRepository(JdbcTemplate jdbc) {
34	        this.jdbc = jdbc;
35	    }
36	
37	    public long insert(long releaseId, String deviceId) {
38	        KeyHolder keyHolder = new GeneratedKeyHolder();
39	        jdbc.update(con -> {
40	            PreparedStatement ps = con.prepareStatement(
41	                    "INSERT INTO rollout_task (release_id, device_id, status) VALUES (?, ?, 'PENDING')",
42	                    new String[]{"id"});
43	            ps.setLong(1, releaseId);
44	            ps.setString(2, deviceId);
45	            return ps;
46	        }, keyHolder);
