33	import static org.assertj.core.api.Assertions.assertThat;
34	
35	/**
36	 * 并发与幂等边界测试：真实并发打到 H2 事务与唯一约束上，验证一致提交顺序。
37	 */
38	@SpringBootTest
39	class FirmwareConcurrencyTest {
40	
41	    @Autowired
42	    private DeviceService deviceService;
43	
44	    @Autowired
45	    private ReleaseService releaseService;
46	
47	    @Autowired
48	    private TaskService taskService;
49	
50	    @Autowired
51	    private TaskRepository taskRepository;
52	
53	    @Autowired
54	    private ReleaseRepository releaseRepository;
55	
56	    @Autowired
57	    private JdbcTemplate jdbc;
58	
59	    private ExecutorService executor;
60	
61	    @BeforeEach
62	    void setUp() {
63	        jdbc.update("DELETE FROM rollout_task");
64	        jdbc.update("DELETE FROM release_order");
65	        jdbc.update("DELETE FROM device");
66	        jdbc.update("DELETE FROM idempotency_record");
67	        executor = Executors.newFixedThreadPool(8);
68	    }
69	
70	    @AfterEach
71	    void tearDown() throws InterruptedException {
72	        executor.shutdownNow();
73	        assertThat(executor.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
74	    }
75	
76	    /**
77	     * 闩锁对齐后并发执行，收集成功结果与异常。
78	     */
79	    private <T> List<Object> runConcurrently(List<Callable<T>> tasks) throws Exception {
80	        CountDownLatch ready = new CountDownLatch(tasks.size());
81	        CountDownLatch start = new CountDownLatch(1);
82	        List<Future<Object>> futures = new ArrayList<>();
83	        for (Callable<T> task : tasks) {
84	            futures.add(executor.submit(() -> {
85	                ready.countDown();
86	                start.await(5, TimeUnit.SECONDS);
87	                try {
88	                    return task.call();
89	                } catch (Exception e) {
90	                    return e;
91	                }
92	            }));
93	        }
94	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
95	        start.countDown();
96	        List<Object> results = new ArrayList<>();
97	        for (Future<Object> future : futures) {
98	            results.add(future.get(30, TimeUnit.SECONDS));
99	        }
100	        return results;
101	    }
102	
103	    @Test
104	    void 并发拉取_同设备同发布单最多一条任务() throws Exception {
105	        deviceService.register(new RegisterDeviceRequest("req-d", "d1", "m1", "1.0.0", 5));
106	        long releaseId = releaseService.create(new CreateReleaseRequest("req-r", "m1", "1.0.0", "2.0.0", 100))
107	                .releaseId();
108	
109	        int threads = 8;
110	        List<Callable<PullResponse>> tasks = new ArrayList<>();
111	        for (int i = 0; i < threads; i++) {
112	            int seq = i;
113	            tasks.add(() -> taskService.pull("d1", "req-pull-" + seq));
114	        }
115	        List<Object> results = runConcurrently(tasks);
116	
117	        List<Long> taskIds = new ArrayList<>();
118	        for (Object result : results) {
119	            assertThat(result).isInstanceOf(PullResponse.class);
120	            PullResponse response = (PullResponse) result;
